(()=>{const e=document.querySelector(".footer-signature");if(!e)return;const s=e.dataset.language==="zh-tw",n=s?["持續學習中。","再做一次實驗。","保持好奇。","Reviewer #2 已進入聊天室。"]:["still learning.","one more experiment.","stay curious.","Reviewer #2 has entered the chat."];let t=0;e.disabled=!1,e.addEventListener("click",()=>{t=(t+1)%n.length,e.querySelector(".signature-text").textContent=n[t]})})()